import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import java.nio.file.*;import java.util.*;
class NumberFormatInfoRangeFailuresProbe {
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static void set(NumberFormatInfo n,String property,int value){switch(property){case "NumberDecimalDigits"->n.set_NumberDecimalDigits(value);case "CurrencyDecimalDigits"->n.set_CurrencyDecimalDigits(value);case "PercentDecimalDigits"->n.set_PercentDecimalDigits(value);case "NumberNegativePattern"->n.set_NumberNegativePattern(value);case "CurrencyPositivePattern"->n.set_CurrencyPositivePattern(value);case "CurrencyNegativePattern"->n.set_CurrencyNegativePattern(value);case "PercentPositivePattern"->n.set_PercentPositivePattern(value);case "PercentNegativePattern"->n.set_PercentNegativePattern(value);default->throw new AssertionError(property);}}
 static String snapshot(NumberFormatInfo n){return n.get_NumberDecimalDigits()+","+n.get_CurrencyDecimalDigits()+","+n.get_PercentDecimalDigits()+","+n.get_NumberNegativePattern()+","+n.get_CurrencyPositivePattern()+","+n.get_CurrencyNegativePattern()+","+n.get_PercentPositivePattern()+","+n.get_PercentNegativePattern();}
 static String outcome(NumberFormatInfo n,String property,int value){try{set(n,property,value);return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String actual,String expected,String context){if(!actual.equals(expected))throw new AssertionError(context+" actual="+actual+" expected="+expected);}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);NumberFormatInfo n=new NumberFormatInfo();set(n,p[0],Integer.parseInt(p[1]));check(snapshot(n),p[4],"before "+line);check(outcome(n,p[0],Integer.parseInt(p[2])),p[3],"result "+line);check(snapshot(n),p[5],"after "+line);cases++;groups+=3;}java.lang.System.out.println("PASS NumberFormatInfo ranges cases="+cases+" groups="+groups);}
}
